window.BlessData.files["Sources-BlessProviders"] = {"group":"Sources-BlessProviders","files":[{"path":"Sources/BlessProviders/BlessProviders.swift","status":"added","lang":"swift","hunks":[[1,0,1,13]],"header":{"lines":[1,13],"target":"BlessProviders","what":[8,11],"pin":[12,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":237,"scopes":[],"old":"","new":"//\n//  BlessProviders.swift\n//  BlessProviders\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The module's front page. One InferenceProvider, OpenAICompatibleProvider, speaks the\n//        chat-completions wire every mainstream layer shares (choices[], server-sent events), with\n//        presets for OpenAI, Mistral and AII's Sewn. Wrap it in Bless's Blessed and nothing it says\n//        reaches a user unread.\n//  PIN:  Kept out of the core so Bless itself never touches the network.\n//\n"},{"path":"Sources/BlessProviders/OpenAICompatibleProvider.swift","status":"added","lang":"swift","hunks":[[1,0,1,134]],"header":{"lines":[1,12],"target":"BlessProviders","what":[8,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":237,"scopes":[["E","ProviderError",null,"public",17,17,[17,69],31,null,-1,0,"a",["missingAPIKey","http","decoding","noChoices"]],["v","description",null,"public",23,23,[23,35],30,null,0,0,"a"],["S","OpenAICompatibleProvider",null,"public",33,33,[33,58],134,null,-1,0,"a"],["i","init",["preset","apiKey","session"],"public",38,38,[38,80],42,null,2,0,"a"],["v","name",null,"public",44,44,[44,28],44,null,2,8,"a"],["f","complete",["_"],"public",46,46,[46,78],56,null,2,0,"a"],["f","stream",["_"],"public",58,58,[58,92],93,null,2,0,"a"],["f","deliver",["_"],"",73,73,[73,65],81,null,6,4,"a"],["f","models",[],"public",96,96,[96,50],106,[95,95],2,0,"a"],["f","urlRequest",["_","stream"],"private",108,108,[108,87],118,null,2,0,"a"],["f","authorize",["_"],"private",120,120,[120,63],127,null,2,0,"a"],["f","check",["_","body"],"private",129,129,[129,67],133,null,2,0,"a"]],"old":"","new":"//\n//  OpenAICompatibleProvider.swift\n//  BlessProviders\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: An InferenceProvider for any layer that speaks the chat-completions wire: POST\n//        `<base>/chat/completions` with a bearer key, whole (`complete`) or as server-sent\n//        events (`stream`), plus `models()` to list what the key can use (the playground's\n//        key check). Errors keep the HTTP status and the start of the body, never the key.\n//\n\nimport Bless\nimport Foundation\n\npublic enum ProviderError: Error, Equatable, CustomStringConvertible {\n    case missingAPIKey\n    case http(status: Int, body: String)\n    case decoding(String)\n    case noChoices\n\n    public var description: String {\n        switch self {\n        case .missingAPIKey: \"this provider needs an API key\"\n        case .http(let status, let body): \"HTTP \\(status)\\(body.isEmpty ? \"\" : \": \\(body)\")\"\n        case .decoding(let why): \"the reply did not decode: \\(why)\"\n        case .noChoices: \"the reply had no choices\"\n        }\n    }\n}\n\npublic struct OpenAICompatibleProvider: InferenceProvider {\n    public let preset: Preset\n    private let apiKey: String?\n    private let session: URLSession\n\n    public init(preset: Preset, apiKey: String?, session: URLSession = .shared) {\n        self.preset = preset\n        self.apiKey = apiKey.flatMap { $0.isEmpty ? nil : $0 }\n        self.session = session\n    }\n\n    public var name: String { preset.name }\n\n    public func complete(_ request: ChatRequest) async throws -> ChatResponse {\n        let (data, response) = try await session.data(for: try urlRequest(request, stream: false))\n        try check(response, body: data)\n        do {\n            return try Wire.response(try JSONDecoder().decode(Wire.Response.self, from: data), model: request.model)\n        } catch let error as ProviderError {\n            throw error\n        } catch {\n            throw ProviderError.decoding(String(describing: error).prefix(200).description)\n        }\n    }\n\n    public func stream(_ request: ChatRequest) -> AsyncThrowingStream<ChatDelta, any Error> {\n        AsyncThrowingStream { continuation in\n            let task = Task {\n                do {\n                    let (bytes, response) = try await session.bytes(for: try urlRequest(request, stream: true))\n                    if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {\n                        var body = Data()\n                        for try await byte in bytes {\n                            body.append(byte)\n                            if body.count >= 2048 { break }\n                        }\n                        try check(response, body: body)\n                    }\n                    var parser = SSEParser()\n                    let decoder = JSONDecoder()\n                    func deliver(_ event: String) throws -> Bool {\n                        if event == \"[DONE]\" { return false }\n                        do {\n                            continuation.yield(Wire.delta(try decoder.decode(Wire.Response.self, from: Data(event.utf8))))\n                        } catch {\n                            throw ProviderError.decoding(\"a stream event: \\(event.prefix(120))\")\n                        }\n                        return true\n                    }\n                    reading: for try await byte in bytes {\n                        if let event = parser.feed(byte), try !deliver(event) { break reading }\n                    }\n                    if let event = parser.finish() { _ = try deliver(event) }\n                    continuation.finish()\n                } catch {\n                    continuation.finish(throwing: error)\n                }\n            }\n            continuation.onTermination = { _ in task.cancel() }\n        }\n    }\n\n    /// The ids of the models this key can use (`GET <base>/models`).\n    public func models() async throws -> [String] {\n        var request = URLRequest(url: preset.modelsURL)\n        try authorize(&request)\n        let (data, response) = try await session.data(for: request)\n        try check(response, body: data)\n        do {\n            return try JSONDecoder().decode(Wire.ModelList.self, from: data).data.map(\\.id)\n        } catch {\n            throw ProviderError.decoding(\"the model list\")\n        }\n    }\n\n    private func urlRequest(_ request: ChatRequest, stream: Bool) throws -> URLRequest {\n        var out = URLRequest(url: preset.completionsURL)\n        out.httpMethod = \"POST\"\n        out.setValue(\"application/json\", forHTTPHeaderField: \"Content-Type\")\n        out.setValue(stream ? \"text/event-stream\" : \"application/json\", forHTTPHeaderField: \"Accept\")\n        try authorize(&out)\n        let encoder = JSONEncoder()\n        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]\n        out.httpBody = try encoder.encode(Wire.request(request, preset: preset, stream: stream))\n        return out\n    }\n\n    private func authorize(_ request: inout URLRequest) throws {\n        for (field, value) in preset.headers { request.setValue(value, forHTTPHeaderField: field) }\n        if let apiKey {\n            request.setValue(\"Bearer \\(apiKey)\", forHTTPHeaderField: \"Authorization\")\n        } else if preset.requiresKey {\n            throw ProviderError.missingAPIKey\n        }\n    }\n\n    private func check(_ response: URLResponse, body: Data) throws {\n        guard let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) else { return }\n        let text = String(decoding: body.prefix(600), as: UTF8.self).trimmingCharacters(in: .whitespacesAndNewlines)\n        throw ProviderError.http(status: http.statusCode, body: text)\n    }\n}\n"},{"path":"Sources/BlessProviders/Preset.swift","status":"added","lang":"swift","hunks":[[1,0,1,58]],"header":{"lines":[1,15],"target":"BlessProviders","what":[8,11],"pin":[12,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":249,"scopes":[["S","Preset",null,"public",20,20,[20,42],58,null,-1,0,"a"],["i","init",["name","baseURL","completionsPath","modelsPath","headers","extra","requiresKey"],"public",30,30,[31,109],39,null,0,0,"a"],["f","sewn",["baseURL","sewn"],"public static",46,46,[47,65],49,[45,45],0,0,"a"],["f","custom",["name","baseURL","requiresKey"],"public static",52,52,[52,95],54,[51,51],0,0,"a"],["v","completionsURL",null,"",56,56,[56,28],56,null,0,8,"a"],["v","modelsURL",null,"",57,57,[57,23],57,null,0,8,"a"]],"old":"","new":"//\n//  Preset.swift\n//  BlessProviders\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where an OpenAI-compatible layer lives and what it needs: its base URL, the paths of\n//        its chat-completions and model-list endpoints, any fixed headers, and top-level fields\n//        every request must carry. OpenAI, Mistral and AII's Sewn are named; `custom` covers\n//        the rest (vLLM, Ollama, LM Studio, a hospital's own gateway).\n//  PIN:  Sewn's /v1/chat/completions is OpenAI-shaped but requires a `sewn` object (owner and\n//        scope); it rides in `extra`, and a request's own `extra` wins per key. Sewn listens on\n//        loopback 47080 (AII's README).\n//\n\nimport Bless\nimport Foundation\n\npublic struct Preset: Sendable, Equatable {\n    public var name: String\n    public var baseURL: URL\n    public var completionsPath: String\n    public var modelsPath: String\n    public var headers: [String: String]\n    public var extra: [String: JSONValue]\n    /// Whether requests need a bearer key.\n    public var requiresKey: Bool\n\n    public init(name: String, baseURL: URL, completionsPath: String = \"chat/completions\", modelsPath: String = \"models\",\n                headers: [String: String] = [:], extra: [String: JSONValue] = [:], requiresKey: Bool = true) {\n        self.name = name\n        self.baseURL = baseURL\n        self.completionsPath = completionsPath\n        self.modelsPath = modelsPath\n        self.headers = headers\n        self.extra = extra\n        self.requiresKey = requiresKey\n    }\n\n    public static let openAI = Preset(name: \"openai\", baseURL: URL(string: \"https://api.openai.com/v1\")!)\n\n    public static let mistral = Preset(name: \"mistral\", baseURL: URL(string: \"https://api.mistral.ai/v1\")!)\n\n    /// AII's Sewn on this Mac, with the `sewn` object its chat route requires.\n    public static func sewn(baseURL: URL = URL(string: \"http://127.0.0.1:47080/v1\")!,\n                            sewn: [String: JSONValue]) -> Preset {\n        Preset(name: \"sewn\", baseURL: baseURL, extra: [\"sewn\": .object(sewn)], requiresKey: false)\n    }\n\n    /// Any other layer that speaks the same wire.\n    public static func custom(name: String, baseURL: URL, requiresKey: Bool = false) -> Preset {\n        Preset(name: name, baseURL: baseURL, requiresKey: requiresKey)\n    }\n\n    var completionsURL: URL { baseURL.appending(path: completionsPath) }\n    var modelsURL: URL { baseURL.appending(path: modelsPath) }\n}\n"},{"path":"Sources/BlessProviders/SSE.swift","status":"added","lang":"swift","hunks":[[1,0,1,57]],"header":{"lines":[1,13],"target":"BlessProviders","what":[8,10],"pin":[11,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":255,"scopes":[["S","SSEParser",null,"",17,17,[17,17],57,null,-1,0,"a"],["f","feed",["_"],"mutating",22,22,[22,49],30,[21,21],0,0,"a"],["f","finish",[],"mutating",33,33,[33,38],39,[32,32],0,0,"a"],["f","take",["_"],"private mutating",41,41,[41,59],50,null,0,0,"a"],["f","flush",[],"private mutating",52,52,[52,45],56,null,0,0,"a"]],"old":"","new":"//\n//  SSE.swift\n//  BlessProviders\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Server-sent events, byte by byte: `data:` lines are gathered until a blank line ends the\n//        event, comment lines (`:`) and other fields are ignored, CRLF is read as LF, and an\n//        event still open when the stream ends is delivered. The chat stream ends at `[DONE]`.\n//  PIN:  Fed bytes, not lines: Foundation's async `lines` drops blank lines, and the blank line\n//        is what ends an event (checked on this Mac, 2026-10-20).\n//\n\nimport Foundation\n\nstruct SSEParser {\n    private var line: [UInt8] = []\n    private var data: [String] = []\n\n    /// Feeds one byte; returns an event's data when this byte completes one.\n    mutating func feed(_ byte: UInt8) -> String? {\n        guard byte == 0x0A else {\n            line.append(byte)\n            return nil\n        }\n        if line.last == 0x0D { line.removeLast() }\n        defer { line.removeAll(keepingCapacity: true) }\n        return take(line)\n    }\n\n    /// The event still open at the end of the stream, if any.\n    mutating func finish() -> String? {\n        if !line.isEmpty {\n            if let event = take(line) { return event }\n            line.removeAll()\n        }\n        return flush()\n    }\n\n    private mutating func take(_ line: [UInt8]) -> String? {\n        if line.isEmpty { return flush() }\n        if line.first == 0x3A { return nil }  // \":\" comment\n        let text = String(decoding: line, as: UTF8.self)\n        guard text.hasPrefix(\"data:\") else { return nil }\n        var value = text.dropFirst(5)\n        if value.first == \" \" { value = value.dropFirst() }\n        data.append(String(value))\n        return nil\n    }\n\n    private mutating func flush() -> String? {\n        guard !data.isEmpty else { return nil }\n        defer { data.removeAll() }\n        return data.joined(separator: \"\\n\")\n    }\n}\n"},{"path":"Sources/BlessProviders/Wire.swift","status":"added","lang":"swift","hunks":[[1,0,1,148]],"header":{"lines":[1,14],"target":"BlessProviders","what":[8,11],"pin":[12,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":260,"scopes":[["E","Wire",null,"",19,19,[19,10],148,null,-1,0,"a",[]],["S","Message",null,"",20,20,[20,28],23,null,0,0,"a"],["S","Content",null,"",26,26,[26,28],50,[25,25],0,0,"a"],["i","init",["_"],"",29,29,[29,29],29,null,2,8,"a"],["i","init",["from"],"",31,31,[31,47],39,null,2,0,"a"],["f","encode",["to"],"",41,41,[41,52],44,null,2,0,"a"],["S","Part",null,"",46,46,[46,31],49,null,2,0,"a"],["S","Request",null,"",52,52,[52,30],81,null,0,0,"a"],["S","Key",null,"private",60,60,[60,38],66,null,7,0,"a"],["v","intValue",null,"",62,62,[62,31],62,null,8,8,"a"],["i","init",["_"],"",63,63,[63,35],63,null,8,8,"a"],["i","init",["stringValue"],"",64,64,[64,39],64,null,8,8,"a"],["i","init",["intValue"],"",65,65,[65,33],65,null,8,8,"a"],["f","encode",["to"],"",70,70,[70,52],80,null,7,0,"a"],["S","Usage",null,"",83,83,[83,28],91,null,0,0,"a"],["E","CodingKeys",null,"",88,88,[88,43],90,null,14,0,"a",["promptTokens","completionTokens","totalTokens"]],["S","Delta",null,"",93,93,[93,28],96,null,0,0,"a"],["S","Choice",null,"",98,98,[98,29],107,null,0,0,"a"],["E","CodingKeys",null,"",104,104,[104,43],106,null,17,0,"a",["index","message","delta","finishReason"]],["S","Response",null,"",109,109,[109,31],115,null,0,0,"a"],["S","ModelList",null,"",117,117,[117,32],120,null,0,0,"a"],["S","Model",null,"",118,118,[118,32],118,null,20,8,"a"],["f","request",["_","preset","stream"],"static",122,122,[122,89],127,null,0,0,"a"],["f","response",["_","model"],"static",129,129,[129,81],139,null,0,0,"a"],["f","delta",["_"],"static",141,141,[141,53],147,null,0,0,"a"]],"old":"","new":"//\n//  Wire.swift\n//  BlessProviders\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The chat-completions wire every mainstream layer shares, and its mapping to Bless's\n//        neutral types: a request with snake_case keys and the preset's and request's `extra`\n//        fields merged at the top level; a response's `choices[0].message`; a stream chunk's\n//        `choices[0].delta`.\n//  PIN:  `content` may be a string, null, or (Mistral's reasoning models) an array of typed parts;\n//        only `text` parts are read. Sewn's `refusal` and unknown fields are ignored.\n//\n\nimport Bless\nimport Foundation\n\nenum Wire {\n    struct Message: Codable {\n        var role: String\n        var content: Content?\n    }\n\n    /// A message's content as the wire writes it.\n    struct Content: Codable {\n        var text: String\n\n        init(_ text: String) { self.text = text }\n\n        init(from decoder: any Decoder) throws {\n            let container = try decoder.singleValueContainer()\n            if let text = try? container.decode(String.self) {\n                self.text = text\n            } else {\n                let parts = try container.decode([Part].self)\n                self.text = parts.filter { $0.type == \"text\" }.compactMap(\\.text).joined()\n            }\n        }\n\n        func encode(to encoder: any Encoder) throws {\n            var container = encoder.singleValueContainer()\n            try container.encode(text)\n        }\n\n        struct Part: Decodable {\n            var type: String\n            var text: String?\n        }\n    }\n\n    struct Request: Encodable {\n        var model: String\n        var messages: [Message]\n        var temperature: Double?\n        var maxTokens: Int?\n        var stream: Bool\n        var extra: [String: JSONValue]\n\n        private struct Key: CodingKey {\n            var stringValue: String\n            var intValue: Int? { nil }\n            init(_ string: String) { stringValue = string }\n            init?(stringValue: String) { self.stringValue = stringValue }\n            init?(intValue: Int) { nil }\n        }\n\n        static let standard: Set<String> = [\"model\", \"messages\", \"temperature\", \"max_tokens\", \"stream\"]\n\n        func encode(to encoder: any Encoder) throws {\n            var c = encoder.container(keyedBy: Key.self)\n            try c.encode(model, forKey: Key(\"model\"))\n            try c.encode(messages, forKey: Key(\"messages\"))\n            try c.encodeIfPresent(temperature, forKey: Key(\"temperature\"))\n            try c.encodeIfPresent(maxTokens, forKey: Key(\"max_tokens\"))\n            try c.encode(stream, forKey: Key(\"stream\"))\n            for (key, value) in extra where !Self.standard.contains(key) {\n                try c.encode(value, forKey: Key(key))\n            }\n        }\n    }\n\n    struct Usage: Decodable {\n        var promptTokens: Int?\n        var completionTokens: Int?\n        var totalTokens: Int?\n\n        enum CodingKeys: String, CodingKey {\n            case promptTokens = \"prompt_tokens\", completionTokens = \"completion_tokens\", totalTokens = \"total_tokens\"\n        }\n    }\n\n    struct Delta: Decodable {\n        var role: String?\n        var content: Content?\n    }\n\n    struct Choice: Decodable {\n        var index: Int?\n        var message: Message?\n        var delta: Delta?\n        var finishReason: String?\n\n        enum CodingKeys: String, CodingKey {\n            case index, message, delta, finishReason = \"finish_reason\"\n        }\n    }\n\n    struct Response: Decodable {\n        var id: String?\n        var model: String?\n        var created: Int?\n        var choices: [Choice]\n        var usage: Usage?\n    }\n\n    struct ModelList: Decodable {\n        struct Model: Decodable { var id: String }\n        var data: [Model]\n    }\n\n    static func request(_ request: ChatRequest, preset: Preset, stream: Bool) -> Request {\n        Request(model: request.model,\n                messages: request.messages.map { Message(role: $0.role.rawValue, content: Content($0.content)) },\n                temperature: request.temperature, maxTokens: request.maxTokens, stream: stream,\n                extra: preset.extra.merging(request.extra ?? [:]) { _, own in own })\n    }\n\n    static func response(_ wire: Response, model: String) throws -> ChatResponse {\n        guard let choice = wire.choices.first, let message = choice.message else { throw ProviderError.noChoices }\n        let usage = wire.usage.map {\n            ChatResponse.Usage(promptTokens: $0.promptTokens ?? 0, completionTokens: $0.completionTokens ?? 0,\n                               totalTokens: $0.totalTokens ?? (($0.promptTokens ?? 0) + ($0.completionTokens ?? 0)))\n        }\n        return ChatResponse(id: wire.id ?? \"chat-\\(UUID().uuidString.lowercased())\", model: wire.model ?? model,\n                            message: .assistant(message.content?.text ?? \"\"),\n                            finishReason: choice.finishReason.map(FinishReason.init(wire:)), usage: usage,\n                            created: wire.created.map { Date(timeIntervalSince1970: TimeInterval($0)) })\n    }\n\n    static func delta(_ wire: Response) -> ChatDelta {\n        let choice = wire.choices.first\n        return ChatDelta(role: choice?.delta?.role.flatMap(ChatRole.init(rawValue:)),\n                         content: choice?.delta?.content?.text,\n                         finishReason: choice?.finishReason.map(FinishReason.init(wire:)),\n                         id: wire.id, model: wire.model)\n    }\n}\n"}]};
